#!/usr/bin/env python3
"""Benchmark Casanovo on one input file across compute devices, and emit a comparison table.

Answers the questions a user asks before committing to a run: is a GPU required, how long does
this take on each, how many spectra per second, and how much memory does it need.

What is measured
----------------
* **Total time** -- wall clock for the whole invocation, including model loading, reading the
  spectrum file and writing the mzTab. This is what a user actually waits through.
* **Peak private RAM** -- sampled private memory of the process tree. Shared pages and
  other applications need additional RAM, so this is not a minimum system requirement.

The table reports those, plus the spectrum count and the rate derived from it. Prediction time
(Casanovo's "Time Elapsed", which excludes writing the result), peak device memory and peak
tensor memory are recorded in benchmark.json only: the memory a run happened to occupy is not
the memory it needs. Use --gpu-memory-budgets to test that directly, in the same report.
See docs/performance.md.

Each device gets a complete configuration generated by `casanovo configure`, with only the
accelerator changed; Casanovo rejects a configuration file that omits any key, so a minimal
one is not an option. CPU runs additionally hide every GPU from the subprocess, so that "CPU"
means the CPU.

Usage:
    python speed_benchmark.py --input run.mzML --casanovo /path/to/casanovo \\
        [--devices gpu cpu] [--out-dir bench]

Requires psutil (a Casanovo dependency, so the Casanovo environment's Python has it).
"""

from __future__ import annotations

import argparse
import json
import os
import platform
import re
import subprocess
import sys
import threading
import time
import xml.etree.ElementTree as ET
from dataclasses import dataclass, asdict
from pathlib import Path

try:
    import psutil
except ImportError:  # pragma: no cover
    sys.exit("psutil is required; run this with the Casanovo environment's Python.")


# --------------------------------------------------------------------------- machine details


def _run(cmd: list[str]) -> str:
    try:
        out = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        return out.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        return ""


def cpu_name() -> str:
    if sys.platform == "win32":
        name = _run(["powershell", "-NoProfile", "-Command",
                     "(Get-CimInstance Win32_Processor).Name"])
        if name:
            return " ".join(name.split())
    elif sys.platform == "darwin":
        name = _run(["sysctl", "-n", "machdep.cpu.brand_string"])
        if name:
            return name
    else:
        try:
            for line in Path("/proc/cpuinfo").read_text().splitlines():
                if line.startswith("model name"):
                    return line.split(":", 1)[1].strip()
        except OSError:
            pass
    return platform.processor() or "unknown CPU"


def os_name() -> str:
    """A truthful OS label.

    platform.release() reports "10" on Windows 11, because Microsoft kept the major version
    at 10; the build number is what distinguishes them (11 starts at build 22000).
    """
    if sys.platform == "win32":
        build = 0
        try:
            build = int(platform.version().split(".")[-1])
        except (ValueError, IndexError):
            pass
        return f"Windows {'11' if build >= 22000 else '10'} (build {build})" if build \
            else f"Windows {platform.release()}"
    if sys.platform == "darwin":
        return f"macOS {platform.mac_ver()[0] or platform.release()}"
    return f"{platform.system()} {platform.release()}"


def gpu_name() -> tuple[str, str]:
    """(name, driver version) from nvidia-smi, or ("", "") when there is no NVIDIA GPU."""
    out = _run(["nvidia-smi", "--query-gpu=name,driver_version", "--format=csv,noheader"])
    if not out:
        return "", ""
    first = out.splitlines()[0]
    parts = [p.strip() for p in first.split(",")]
    return (parts[0], parts[1]) if len(parts) >= 2 else (first, "")


def casanovo_version(casanovo: Path) -> str:
    """The installed Casanovo version -- the variable this benchmark exists to track."""
    env = {**os.environ, "KMP_DUPLICATE_LIB_OK": "TRUE"}
    try:
        out = subprocess.run([str(casanovo), "version"], capture_output=True, text=True,
                             timeout=300, env=env)
        found = re.search(r"Casanovo Version:\s*(\S+)", out.stdout + out.stderr)
        return found.group(1) if found else "unknown"
    except (OSError, subprocess.SubprocessError):
        return "unknown"


def torch_build(python: Path) -> str:
    code = ("import torch;"
            "print(torch.__version__ + ('' if torch.version.cuda is None"
            " else ' (CUDA ' + torch.version.cuda + ')'))")
    env = {**os.environ, "KMP_DUPLICATE_LIB_OK": "TRUE"}
    try:
        out = subprocess.run([str(python), "-c", code], capture_output=True, text=True,
                             timeout=180, env=env)
        return out.stdout.strip() or "unknown"
    except (OSError, subprocess.SubprocessError):
        return "unknown"


def gui_version() -> str:
    """Version of the GUI source tree containing this benchmark script."""
    try:
        pom = ET.parse(Path(__file__).resolve().parents[2] / "pom.xml")
        return pom.findtext("{http://maven.apache.org/POM/4.0.0}version") or "unknown"
    except (OSError, ET.ParseError):
        return "unknown"


# --------------------------------------------------------------------------- one measured run


@dataclass
class Result:
    device: str
    hardware: str
    spectra: int
    total_seconds: float
    predict_seconds: float | None
    peak_host_gb: float | None
    peak_gpu_mib: int | None          # device memory attributed to this run
    gpu_per_process: bool             # False when measured as a rise above baseline
    gpu_baseline_mib: int | None      # other GPU use at launch; small means the delta is
                                      # sound, None when nvidia-smi did not answer
    peak_gpu_tensors_mib: int | None  # peak tensor memory PyTorch allocated (Casanovo's report)
    exit_code: int

    @property
    def total_rate(self) -> float:
        return self.spectra / self.total_seconds if self.total_seconds else 0.0

    @property
    def predict_rate(self) -> float | None:
        if not self.predict_seconds:
            return None
        return self.spectra / self.predict_seconds


def gpu_process_memory(pids: set[int]) -> int | None:
    """Device memory in MiB attributed to `pids` by nvidia-smi, or None where unavailable.

    NVIDIA does not provide per-process memory when the card is in WDDM mode -- the usual
    mode on a Windows desktop -- and reports "[N/A]" instead. Returning None there is what
    lets the caller fall back rather than silently record zero.
    """
    out = _run(["nvidia-smi", "--query-compute-apps=pid,used_memory",
                "--format=csv,noheader,nounits"])
    total = 0
    matched = False
    for line in out.splitlines():
        parts = [p.strip() for p in line.split(",")]
        if len(parts) != 2:
            continue
        try:
            pid = int(parts[0])
        except ValueError:
            continue
        if pid in pids:
            if not parts[1].isdigit():
                return None  # "[N/A]": this driver mode cannot attribute memory per process
            total += int(parts[1])
            matched = True
    return total if matched else None


def gpu_total_memory() -> int | None:
    """Total device memory in use, in MiB, across everything on the card, or None.

    None when nvidia-smi could not be asked, or answered with something that is not a
    number. A failed probe must not read as an idle card: this figure is the baseline
    every later sample is measured against, so a wrong 0 would publish the card's whole
    in-use total as this run's peak -- under a baseline claiming the card was idle.
    """
    out = _run(["nvidia-smi", "--query-gpu=memory.used", "--format=csv,noheader,nounits"])
    line = out.splitlines()[0] if out else ""
    return int(line) if line.strip().isdigit() else None


#: Sampling period. Short peaks may be missed. USS is costly to compute (it walks the working
#: set), enough that sampling it four times a second across ~20 dataloader workers nearly
#: doubled the measured runtime of a CPU run. Measuring must not change what is being measured.
POLL_SECONDS = 2.0


def process_memory(proc: psutil.Process) -> tuple[int | None, set[int]]:
    """(bytes attributable to this process tree, the tree's pids).

    Uses the unique set size where the platform provides it. Summing RSS over a tree
    double-counts every shared page -- the interpreter, the shared libraries, and the
    copy-on-write pages a DataLoader's workers inherit -- which would materially overstate
    the footprint of a multi-worker run. USS excludes shared pages entirely.
    """
    total = 0
    readings = 0
    pids = set()
    for target in [proc] + proc.children(recursive=True):
        try:
            pids.add(target.pid)
            try:
                total += target.memory_full_info().uss
            except (psutil.AccessDenied, AttributeError):
                total += target.memory_info().rss  # USS unavailable: RSS is the upper bound
            readings += 1
        except psutil.Error:
            pass
    return (total if readings else None), pids


def prediction_seconds(text: str) -> float | None:
    """Parse Casanovo's timedelta report, including runs longer than one day."""
    elapsed = re.search(r"Time Elapsed:\s*(?:(\d+)\s+days?,\s*)?(\d+):(\d+):([\d.]+)", text)
    if not elapsed:
        return None
    days, hours, minutes, seconds = elapsed.groups()
    return int(days or 0) * 86400 + int(hours) * 3600 + int(minutes) * 60 + float(seconds)


def make_config(casanovo: Path, accelerator: str, dest: Path, version: str,
                source: Path | None = None) -> Path:
    """A complete Casanovo config with only the accelerator changed.

    Generated by default, or adapted from an explicitly supplied complete configuration.
    Casanovo requires every key to be present, so a config
    frozen here would break the moment a release adds one. Cached under a filename keyed by
    `version`, not just `dest`, so reusing --out-dir after upgrading casanovo in place
    regenerates the config instead of silently reusing one an older release wrote.
    """
    safe_version = re.sub(r"[^A-Za-z0-9.+-]+", "_", version) or "unknown"
    default = source or dest / f"casanovo-default-{safe_version}.yaml"
    if not default.is_file():
        env = {**os.environ, "KMP_DUPLICATE_LIB_OK": "TRUE",
               "MKL_THREADING_LAYER": "SEQUENTIAL"}
        # Casanovo 5.2.1 raises "Non-relative patterns are unsupported" for an absolute -o
        # path on Windows (casanovo/utils.py check_dir_file_exists globs a non-relative
        # pattern), so run from the destination and pass a bare file name.
        done = subprocess.run([str(casanovo), "configure", "-o", default.name],
                              cwd=str(dest), capture_output=True, text=True, env=env)
        if done.returncode != 0 or not default.is_file():
            # Surface what Casanovo said: a bare CalledProcessError hides the one line that
            # explains the failure, which is the only thing worth having here.
            sys.exit(f"casanovo configure failed (exit {done.returncode}):\n"
                     f"{done.stdout}{done.stderr}")
    text = default.read_text(encoding="utf-8")
    text, n = re.subn(r"^accelerator:.*$", f'accelerator: "{accelerator}"', text,
                      count=1, flags=re.MULTILINE)
    if n == 0:
        sys.exit(f"{default.name} has no top-level 'accelerator:' key to set "
                 f"to {accelerator!r} -- has the config format changed?")
    out = dest / f"config-{accelerator}.yaml"
    out.write_text(text, encoding="utf-8")
    return out


def config_summary(config: Path) -> str:
    """Key inference settings from the saved configuration, for the public report."""
    text = config.read_text(encoding="utf-8")
    values = []
    for key, label in (("predict_batch_size", "batch size"), ("n_beams", "beams"),
                       ("precision", "precision")):
        found = re.search(rf"^{key}:\s*([^\r\n#]+)", text, re.MULTILINE)
        if found:
            value = found[1].strip().strip("\"'")
            values.append(f"{label}: {value}")
    return "; ".join(values) or "see saved configuration"


def measure(casanovo: Path, config: Path, spectra_file: Path, out_dir: Path,
            device: str, hardware: str, *, command: list[str] | None = None,
            env_overrides: dict[str, str | None] | None = None,
            record_samples: bool = False) -> Result:
    out_dir.mkdir(parents=True, exist_ok=True)
    log_path = out_dir / "run.log"

    env = {**os.environ,
           "KMP_DUPLICATE_LIB_OK": "TRUE",
           "MKL_THREADING_LAYER": "SEQUENTIAL",
           "PYTHONIOENCODING": "utf-8", "PYTHONUNBUFFERED": "1"}
    for key, value in (env_overrides or {}).items():
        if value is None:
            env.pop(key, None)
        else:
            env[key] = value
    if device == "cpu":
        # Make "CPU" mean CPU, exactly as the application does (see Os.applyNativeEnv):
        # selecting the CPU accelerator does not by itself stop the stack binding a GPU.
        env["CUDA_VISIBLE_DEVICES"] = "-1"

    # --output_dir/--output_root rather than -o: the same flags the application passes, and
    # unlike -o they accept an absolute path on Windows (see make_config).
    cmd = command or [str(casanovo), "sequence", "--config", str(config), "--force_overwrite",
           "--output_dir", str(out_dir), "--output_root", "result", str(spectra_file)]

    peak_bytes = None
    peak_gpu = None
    gpu_per_process = True
    gpu_baseline = gpu_total_memory() if device != "cpu" else 0
    stop_sampling = threading.Event()
    with log_path.open("w", encoding="utf-8", errors="replace") as log:
        start = time.monotonic()
        proc = subprocess.Popen(cmd, env=env, stdout=log, stderr=subprocess.STDOUT)
        parent = psutil.Process(proc.pid)

        def sample() -> None:
            nonlocal peak_bytes, peak_gpu, gpu_per_process
            # Sample at least once even if the process has already exited by the time this
            # thread runs (a `while proc.poll() is None` loop would otherwise sample zero times
            # for a run shorter than the scheduling delay, reporting a false 0 B peak).
            while True:
                sample_data = {"seconds": time.monotonic() - start}
                try:
                    used, pids = process_memory(parent)
                    sample_data["host_private_bytes"] = used
                    if used is not None:
                        peak_bytes = max(peak_bytes or 0, used)
                    if device != "cpu":
                        attributed = gpu_process_memory(pids)
                        if attributed is None:
                            # WDDM: attribute the rise above the pre-run baseline instead. Sound
                            # only while nothing else is using the card, which is why the
                            # baseline is reported alongside the result. Without a baseline to
                            # measure against, take no sample at all: the card's whole in-use
                            # total is not this run's peak, and a gap beats a wrong figure.
                            gpu_per_process = False
                            total_now = gpu_total_memory()
                            if gpu_baseline is not None and total_now is not None:
                                attributed = max(0, total_now - gpu_baseline)
                        if attributed is not None:
                            peak_gpu = max(peak_gpu or 0, attributed)
                        sample_data.update(gpu_mib=attributed, per_process=gpu_per_process)
                except psutil.Error as exc:
                    sample_data["error"] = str(exc)
                if record_samples:
                    with (out_dir / "samples.jsonl").open("a", encoding="utf-8") as samples:
                        samples.write(json.dumps(sample_data) + "\n")
                if proc.poll() is not None:
                    break
                if stop_sampling.wait(POLL_SECONDS):
                    break

        watcher = threading.Thread(target=sample, daemon=True)
        watcher.start()
        try:
            code = proc.wait()
            total = time.monotonic() - start
        except KeyboardInterrupt:
            for target in parent.children(recursive=True) + [parent]:
                try:
                    target.kill()
                except psutil.Error:
                    pass
            proc.wait()
            raise
        finally:
            stop_sampling.set()
            watcher.join()

    # Casanovo writes its own log beside the result as well; read whichever has the report.
    text = log_path.read_text(encoding="utf-8", errors="replace")
    for extra in out_dir.glob("*.log"):
        if extra != log_path:
            text += extra.read_text(encoding="utf-8", errors="replace")

    spectra = 0
    for pattern in (r"Sequenced (\d+) spectra", r"dataset contains (\d+) spectra"):
        found = re.findall(pattern, text)
        if found:
            spectra = max(int(n) for n in found)
            break

    predict = prediction_seconds(text)

    tensors_mib = None
    mem = re.search(r"Max GPU Memory Utilization:\s*(\d+)\s*MiB", text)
    if mem:
        tensors_mib = int(mem.group(1))

    return Result(device=device, hardware=hardware, spectra=spectra, total_seconds=total,
                  predict_seconds=predict,
                  peak_host_gb=peak_bytes / 1024 ** 3 if peak_bytes is not None else None,
                  peak_gpu_mib=peak_gpu, gpu_per_process=gpu_per_process,
                  gpu_baseline_mib=gpu_baseline, peak_gpu_tensors_mib=tensors_mib,
                  exit_code=code)


# --------------------------------------------------------------------------- reporting


def render(results: list[Result], context: dict[str, str]) -> str:
    lines = ["## Casanovo benchmark", ""]
    for key in ("Benchmarked", "Input", "Operating system", "CPU", "System memory",
                "GPU", "Casanovo", "CasanovoGUI", "PyTorch", "Model", "Settings"):
        if key in context:
            lines.append(f"- **{key}:** {context[key]}")
    lines.append("")
    lines += [
        "| Device | MS/MS spectra | Total time | Spectra/s | Peak private RAM |",
        "|---|---:|---:|---:|---:|",
    ]
    for r in results:
        ram = f"{r.peak_host_gb:.2f} GiB" if r.peak_host_gb is not None else "n/a"
        lines.append(
            f"| {r.device.upper()} | {r.spectra:,} | {r.total_seconds:,.0f} s |"
            f" {r.total_rate:,.0f} | {ram} |")
    lines += [
        "",
        "Total time includes model loading and result writing. These are single runs per device.",
        "",
        "Private RAM excludes shared pages; the operating system and other applications need extra RAM.",
        "The sampler uses resident memory (RSS) where private memory (USS) is unavailable.",
        "RAM is sampled about every two seconds; brief peaks may be missed.",
    ]
    failures = [r for r in results if r.exit_code != 0]
    if failures:
        lines += ["", "**Runs that failed:** " +
                  ", ".join(f"{r.device} (exit {r.exit_code})" for r in failures)]
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--input", required=True, type=Path, help="spectrum file to sequence")
    parser.add_argument("--casanovo", required=True, type=Path, help="the casanovo executable")
    parser.add_argument("--devices", nargs="+", default=["gpu", "cpu"],
                        choices=["gpu", "cpu", "mps"], help="devices to benchmark")
    parser.add_argument("--out-dir", type=Path, default=Path("benchmark"),
                        help="where to write configs, logs and results")
    parser.add_argument("--gpu-memory-budgets", nargs="+", type=float, metavar="GiB",
                        help="include allocator-budget tests in the release report; an unrestricted GPU baseline is automatic; repeat budgets to repeat runs")
    parser.add_argument("--model", type=Path, help="local checkpoint (required for memory-budget tests)")
    parser.add_argument("--config", type=Path, help="complete config to reuse instead of this Casanovo version's defaults")
    parser.add_argument("--update-doc", type=Path,
                        help="update both speed and memory blocks in this Markdown file after a successful release benchmark")
    args = parser.parse_args()

    if args.gpu_memory_budgets is not None:
        import math
        if any(not math.isfinite(b) or b <= 0 for b in args.gpu_memory_budgets):
            parser.error("Memory budgets must be finite positive GiB values; the baseline is automatic")
        if not args.model or not args.model.is_file():
            parser.error("Memory-budget tests require --model pointing to a local checkpoint")
        if "gpu" not in args.devices:
            parser.error("--gpu-memory-budgets requires gpu in --devices")
        if args.update_doc and "cpu" not in args.devices:
            parser.error("--update-doc requires CPU and GPU results; omit it for GPU-only tests")
    elif args.update_doc:
        parser.error("--update-doc requires --gpu-memory-budgets for a complete release report")
    if args.config and not args.config.is_file():
        parser.error("--config must point to an existing configuration")
    if args.model and not args.model.is_file():
        parser.error("--model must point to a local checkpoint")

    if not args.input.is_file():
        sys.exit(f"Not found: {args.input}")
    if not args.casanovo.is_file():
        sys.exit(f"Not found: {args.casanovo}")

    args.input = args.input.resolve()
    args.casanovo = args.casanovo.resolve()
    args.out_dir = args.out_dir.resolve()
    if args.model:
        args.model = args.model.resolve()
    if args.config:
        args.config = args.config.resolve()

    args.out_dir.mkdir(parents=True, exist_ok=True)
    python = args.casanovo.parent / ("python.exe" if sys.platform == "win32" else "python")

    cpu = cpu_name()
    gpu, driver = gpu_name()
    casanovo_ver = casanovo_version(args.casanovo)
    context = {
        "Input": args.input.name,
        "Operating system": os_name(),
        "CPU": f"{cpu} ({psutil.cpu_count(logical=False)} cores /"
               f" {psutil.cpu_count()} threads)",
        "System memory": f"{psutil.virtual_memory().total / 1024 ** 3:.0f} GiB",
        "GPU": f"{gpu} (driver {driver})" if gpu else "none detected",
        "PyTorch": torch_build(python),
        "Casanovo": casanovo_ver,
        "CasanovoGUI": gui_version(),
        "Benchmarked": time.strftime("%Y-%m-%d"),
    }
    print("\n".join(f"{k}: {v}" for k, v in context.items()), file=sys.stderr)

    if args.gpu_memory_budgets is not None:
        from gpu_memory_benchmark import release_benchmark
        return release_benchmark(args, context)

    results: list[Result] = []
    for device in args.devices:
        if device == "gpu" and not gpu:
            print("skipping gpu: no NVIDIA GPU detected", file=sys.stderr)
            continue
        # Apple Silicon has no separate GPU name to report -- MPS runs on the same chip as the
        # CPU -- so labeling it as bare `cpu` would make an MPS row indistinguishable from a
        # real CPU run in the table.
        hardware = gpu if device == "gpu" else (f"{cpu} (MPS)" if device == "mps" else cpu)
        print(f"\n=== {device} ===", file=sys.stderr, flush=True)
        try:
            config = make_config(args.casanovo, device, args.out_dir, casanovo_ver, args.config)
            context["Settings"] = config_summary(config)
            command = None
            if args.model:
                command = [str(args.casanovo), "sequence", "--config", str(config),
                           "--model", str(args.model), "--force_overwrite", "--output_dir",
                           str(args.out_dir / device), "--output_root", "result", str(args.input)]
            result = measure(args.casanovo, config, args.input,
                             args.out_dir / device, device, hardware, command=command)
        except (OSError, subprocess.SubprocessError, psutil.Error) as e:
            # Keep whatever devices already succeeded instead of losing them to one bad device.
            print(f"{device}: failed to benchmark ({e}); skipping", file=sys.stderr, flush=True)
            continue
        ram = f"{result.peak_host_gb:.2f} GiB" if result.peak_host_gb is not None else "unavailable"
        print(f"{device}: {result.total_seconds:,.0f} s, {result.spectra:,} spectra, "
              f"{ram} host RAM", file=sys.stderr, flush=True)
        results.append(result)

    table = render(results, context)
    (args.out_dir / "benchmark.md").write_text(table + "\n", encoding="utf-8")
    (args.out_dir / "benchmark.json").write_text(
        json.dumps({"context": context, "results": [asdict(r) for r in results]}, indent=2),
        encoding="utf-8")
    print("\n" + table)
    return 0 if results and all(r.exit_code == 0 for r in results) else 1


if __name__ == "__main__":
    sys.exit(main())
